const rupiah = (value:number) => new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(value).replace('IDR','Rp')
// SPPD-specific Rupiah formatter with standard ",00" decimals (e.g. Rp 24.000.000,00)
const rupiahSppd = (value:number) => new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',minimumFractionDigits:2,maximumFractionDigits:2}).format(Number.isFinite(value)?value:0).replace('IDR','Rp').trim()
// Live grouping formatter for the SPPD input (thousand separators, no forced decimals) — keeps caret natural while typing
const sppdInputDisplay = (value:number) => value>0 ? `Rp ${new Intl.NumberFormat('id-ID').format(value)}` : ''
// Parse whatever the user typed back into a safe integer amount (never NaN)
const parseSppdInput = (raw:string) => { const digits = raw.replace(/\D/g,''); const num = digits ? parseInt(digits,10) : 0; return Number.isNaN(num) ? 0 : num }
// SPPD is stored and displayed as one accumulated total
  const sppdEntries = (b:Budget) => b.sppd > 0 ? [b.sppd] : []
const shortRupiah = (value:number) => value >= 1000000000 ? `Rp ${(value/1000000000).toFixed(1)} M` : `Rp ${(value/1000000).toFixed(0)} Jt`
const statusFor = (end:string, condition?: string, completed?: boolean) => { if (condition === 'Selesai' || completed) return 'Selesai'; if (condition === 'Proses Pembayaran') return 'Proses Pembayaran'; if (Math.floor((Date.now() - new Date(end).getTime()) / 86400000) >= 1) return 'Denda'; if (condition) return condition; return Math.ceil((new Date(end).getTime() - Date.now()) / 86400000) <= 30 ? 'Akan Berakhir' : 'Aktif' }
  // Denda: 1/1000 per hari keterlambatan (maks. 50 hari). Kontrak selesai: dihitung sampai tanggal selesai, lalu tidak bertambah lagi.
  const contractPenalty = (c:Contract) => { const ref = c.completed && c.completedAt ? new Date(c.completedAt).getTime() : Date.now(); const overdueDays = Math.max(0, Math.min(50, Math.floor((ref - new Date(c.end).getTime()) / 86400000))); return overdueDays * c.value / 1000 }
const DAY_MS = 86400000
const MONTHS_ID = ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember']
// Ubah 'YYYY-MM-DD' menjadi '13 Maret 2026' (dipecah manual agar tidak terpengaruh zona waktu)
const formatDateId = (iso:string) => { const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(iso||''); if (!m) return iso || '-'; const month = MONTHS_ID[parseInt(m[2],10)-1]; return month ? `${parseInt(m[3],10)} ${month} ${m[1]}` : iso }
// PPN dihitung dari persentase yang diinput admin (ppnRate, default 11 untuk data lama).
const ppnAmountOf = (c:Contract) => c.ppn ? c.value * ((c.ppnRate ?? 11) / 100) : 0
const contractTotalOf = (c:Contract) => c.value + ppnAmountOf(c)
const realizedSpend = (list:Contract[], wbs:string) => list.filter(c=>c.wbs===wbs && c.completed).reduce((a,c)=>a+contractTotalOf(c)-contractPenalty(c),0)
const lateDaysOf = (c:Contract) => Math.floor((Date.now() - new Date(c.end).getTime()) / DAY_MS)
const daysLeftOf = (c:Contract) => Math.max(0, Math.ceil((new Date(c.end).getTime() - Date.now()) / DAY_MS))
const contractCategory = (c:Contract): 'aktif'|'akan'|'berakhir'|'selesai' => { const st = statusFor(c.end,c.condition,c.completed); return st==='Selesai'?'selesai':(st==='Denda'||st==='Telat')?'berakhir':st==='Akan Berakhir'?'akan':'aktif' }
const overdueTermins = (c:Contract) => c.completed ? [] : c.termins.map((t,i)=>({t,i})).filter(({t})=>t.amount>0 && t.status!=='Terbayar' && Math.floor((Date.now()-new Date(t.deadline).getTime())/DAY_MS)>=1)
const upcomingTermins = (c:Contract) => c.completed ? [] : c.termins.map((t,i)=>({t,i,days:Math.max(0,Math.ceil((new Date(t.deadline).getTime()-Date.now())/DAY_MS))})).filter(({t,days})=>t.amount>0 && t.status!=='Terbayar' && Math.floor((Date.now()-new Date(t.deadline).getTime())/DAY_MS)<1 && days<=14)
// Progres kontrak = nilai termin yang sudah Terbayar dibanding nilai kontrak (maks. 100%); kontrak Selesai = 100%.
const contractProgress = (c:Contract) => { const paid = c.completed ? c.value : Math.min(c.value, c.termins.filter(t=>t.status==='Terbayar').reduce((a,t)=>a+t.amount,0)); const percent = c.completed ? 100 : c.value>0 ? Math.min(100, Math.round(paid/c.value*100)) : 0; return { paid, percent } }
// Data grafik dashboard (semua dihitung dari data kontrak & anggaran yang sama dengan halaman lain)
const monthlyContractValue = (list:Contract[]) => {
  const byMonth = new Map<string,number>()
  list.forEach(c=>{ const k=(c.start||'').slice(0,7); if(/^\d{4}-\d{2}$/.test(k)) byMonth.set(k,(byMonth.get(k)||0)+c.value) })
  const keys=[...byMonth.keys()].sort()
  let months:string[]=[]
  if(keys.length){ let [y,m]=keys[0].split('-').map(Number); const [ey,em]=keys[keys.length-1].split('-').map(Number); while(y<ey||(y===ey&&m<=em)){ months.push(`${y}-${String(m).padStart(2,'0')}`); m++; if(m>12){m=1;y++} } }
  return months.slice(-12).map(k=>({label:`${MONTHS_ID[Number(k.slice(5))-1].slice(0,3)} ${k.slice(2,4)}`,value:byMonth.get(k)||0}))
}
function TrendLineChart({data}:{data:{label:string;value:number}[]}){
  const W=340,H=160,padL=48,padR=12,padT=12,padB=26
  const max=Math.max(1,...data.map(d=>d.value))
  const x=(i:number)=>padL+(data.length<=1?(W-padL-padR)/2:i*(W-padL-padR)/(data.length-1))
  const y=(v:number)=>padT+(H-padT-padB)*(1-v/max)
  return <svg viewBox={`0 0 ${W} ${H}`} className="w-full" role="img" aria-label="Grafik garis nilai kontrak per bulan">{[0,.5,1].map(t=><g key={t}><line x1={padL} x2={W-padR} y1={y(max*t)} y2={y(max*t)} stroke="#e2e8f0" strokeDasharray="3 3"/><text x={padL-6} y={y(max*t)+3} textAnchor="end" fontSize="9" fill="#94a3b8">{shortRupiah(max*t)}</text></g>)}<polyline points={data.map((d,i)=>`${x(i)},${y(d.value)}`).join(' ')} fill="none" stroke="#2874aa" strokeWidth="2.5" strokeLinejoin="round" strokeLinecap="round"/>{data.map((d,i)=><g key={d.label+i}><circle cx={x(i)} cy={y(d.value)} r="3.5" fill="#fff" stroke="#2874aa" strokeWidth="2"><title>{`${d.label}: ${rupiah(d.value)}`}</title></circle>{(data.length<=7||i%2===0)&&<text x={x(i)} y={H-8} textAnchor="middle" fontSize="9" fill="#94a3b8">{d.label}</text>}</g>)}</svg>
}
function PaguBarChart({data}:{data:{label:string;pagu:number;real:number}[]}){
  const W=340,H=170,padL=48,padR=12,padT=12,padB=26
  const max=Math.max(1,...data.flatMap(d=>[d.pagu,d.real]))
  const y=(v:number)=>padT+(H-padT-padB)*(1-v/max)
  const group=(W-padL-padR)/Math.max(1,data.length)
  const bar=Math.min(22,group*0.3)
  return <svg viewBox={`0 0 ${W} ${H}`} className="w-full" role="img" aria-label="Grafik batang pagu dan realisasi per WBS">{[0,.5,1].map(t=><g key={t}><line x1={padL} x2={W-padR} y1={y(max*t)} y2={y(max*t)} stroke="#e2e8f0" strokeDasharray="3 3"/><text x={padL-6} y={y(max*t)+3} textAnchor="end" fontSize="9" fill="#94a3b8">{shortRupiah(max*t)}</text></g>)}{data.map((d,i)=>{const cx=padL+group*i+group/2;return <g key={d.label+i}><rect x={cx-bar-1} y={y(d.pagu)} width={bar} height={Math.max(0,y(0)-y(d.pagu))} rx="3" fill="#4c91be"><title>{`Pagu ${d.label}: ${rupiah(d.pagu)}`}</title></rect><rect x={cx+1} y={y(d.real)} width={bar} height={Math.max(0,y(0)-y(d.real))} rx="3" fill="#e7a62c"><title>{`Realisasi ${d.label}: ${rupiah(d.real)}`}</title></rect><text x={cx} y={H-8} textAnchor="middle" fontSize="9" fill="#94a3b8">{d.label}</text></g>})}</svg>
}
const dashboardStats = (list:Contract[]) => { const n={aktif:0,akan:0,berakhir:0,selesai:0}; list.forEach(c=>{n[contractCategory(c)]++}); const attention=list.filter(c=>{const k=contractCategory(c);return k==='akan'||k==='berakhir'||overdueTermins(c).length>0}).length; const total=list.length; const colors={aktif:'#4c91be',akan:'#e7a62c',berakhir:'#e77b4d',selesai:'#3aa67f'} as const; let acc=0; const parts=(['aktif','akan','berakhir','selesai'] as const).filter(k=>n[k]>0).map(k=>{const from=acc;acc+=n[k]/total*100;return `${colors[k]} ${from}% ${acc}%`}); return {...n,total,attention,gradient: total>0?`conic-gradient(${parts.join(', ')})`:'conic-gradient(#e2e8f0 0 100%)'} }
type AppNotification = {id:string;kind:'end'|'late'|'termin'|'budget';color:'orange'|'blue'|'red';title:string;text:string;contract:boolean;rank:number}
// Notifikasi dihitung langsung dari data kontrak & anggaran yang ada saat ini.
const buildNotifications = (contracts:Contract[], budgets:Budget[]):AppNotification[] => {
  const items:AppNotification[] = []
  contracts.forEach(c=>{
    const cat = contractCategory(c)
    if (cat==='berakhir') { const days=lateDaysOf(c); items.push({id:`late-${c.id}`,kind:'late',color:'red',title:'Kontrak melewati batas waktu',text:`${c.no} melewati tanggal berakhir ${days} hari. Denda berjalan ${rupiah(contractPenalty(c))}${days>=50?' (batas maksimal 5% tercapai)':''}.`,contract:true,rank:0}) }
    if (cat==='akan') { const d=daysLeftOf(c); items.push({id:`end-${c.id}`,kind:'end',color:'orange',title:'Kontrak akan berakhir',text:d===0?`${c.no} berakhir hari ini (${c.end}).`:`${c.no} akan berakhir dalam ${d} hari (${c.end}).`,contract:true,rank:2}) }
    const overdue = overdueTermins(c)
    if (overdue.length>0) items.push({id:`termin-${c.id}-${overdue.map(o=>o.i).join('.')}`,kind:'termin',color:'red',title:'Termin pembayaran',text:`${c.no}: ${overdue.length} termin pembayaran melewati deadline (${rupiah(overdue.reduce((a,o)=>a+o.t.amount,0))} belum dibayar).`,contract:true,rank:1})
    upcomingTermins(c).forEach(u=>items.push({id:`termin-soon-${c.id}-${u.i}`,kind:'termin',color:'orange',title:'Termin pembayaran',text:u.days===0?`Termin ${u.i+1} ${c.no} (${rupiah(u.t.amount)}) jatuh tempo hari ini.`:`Termin ${u.i+1} ${c.no} (${rupiah(u.t.amount)}) jatuh tempo dalam ${u.days} hari.`,contract:true,rank:3}))
  })
  budgets.forEach(b=>{
    if (b.initial<=0) return
    const spent = realizedSpend(contracts,b.wbs)+b.sppd
    const pct = Math.round(spent/b.initial*100)
    if (spent>b.initial) items.push({id:`budget-over-${b.id}`,kind:'budget',color:'red',title:'Realisasi anggaran',text:`Realisasi ${b.activity} (WBS ${b.wbs}) melebihi pagu sebesar ${rupiah(spent-b.initial)}.`,contract:false,rank:1})
    else if (pct>=50) items.push({id:`budget-${b.id}-${Math.floor(pct/10)*10}`,kind:'budget',color:'blue',title:'Realisasi anggaran',text:`Realisasi ${b.activity} (WBS ${b.wbs}) mencapai ${pct}%.`,contract:false,rank:4})
  })
  return items.sort((a,b)=>a.rank-b.rank)
}
const notifIcon = (kind:AppNotification['kind']) => kind==='budget'?<CircleDollarSign size={16}/>:kind==='termin'?<Clock3 size={16}/>:<AlertTriangle size={16}/>
